function LoginEntry({role,onBack,onLogin}:{role:Role;onBack:()=>void;onLogin:(user:AuthUser,token:string)=>void}) {
  const demo=workspaceCredentials[role];
  const [username,setUsername]=useState(demo.username);
  const [password,setPassword]=useState(demo.password);
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState('');
  const submit=async(e:React.FormEvent)=>{
    e.preventDefault(); setLoading(true); setError('');
    try {
      const res=await fetch(`${API_BASE}/api/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});
      const data=await res.json().catch(()=>({}));
      if(!res.ok || !data.token || !data.user?.role) throw new Error(data.message || 'Login failed. Please check the workspace account.');
      if(data.user.role!==role) throw new Error('This account is not authorized for the selected workspace.');
      localStorage.setItem('nirikshan-token',data.token);
      localStorage.setItem('nirikshan-auth-user',JSON.stringify(data.user));
      localStorage.removeItem('nirikshan-role');
      onLogin(data.user as AuthUser,data.token as string);
    } catch(err) { setError(err instanceof Error?err.message:'Unable to reach the NIRIKSHAN API.'); }
    finally { setLoading(false); }
  };
  return <div className="role-entry">
    <div className="role-entry-inner login-entry-inner">
      <button className="btn btn-quiet" onClick={onBack} style={{marginBottom:18}}><ArrowLeft size={15}/> Choose another role</button>
      <div className="role-entry-brand"><div className="brand-mark"><ShieldCheck size={22}/></div><div><div className="role-entry-name">NIRIKSHAN</div><div className="role-entry-sub">PROJECT INTELLIGENCE</div></div></div>
      <div className="role-entry-kicker">Secure workspace access</div>
      <h1 className="role-entry-title">{roleMeta[role].icon} {roleMeta[role].label}</h1>
      <p className="role-entry-copy">Enter the secure workspace for this role. The account credentials are pre-filled for this workspace.</p>
      <form onSubmit={submit} className="panel panel-pad" style={{marginTop:24,textAlign:'left'}}>
        <div className="status status-neutral" style={{display:'inline-flex',marginBottom:16}}>Workspace account · credentials pre-filled</div>
        <label className="login-field"><span>Username:</span><input autoFocus value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username" required className="login-input" placeholder="Username"/></label>
        <label className="login-field"><span>Password:</span><input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required className="login-input" placeholder="Password"/></label>
        <div className="login-helper-row"><span className="forgot-password" aria-disabled="true">Forgot password?</span><span>Recovery is not enabled in this prototype</span></div>
        {error&&<div className="login-error"><LockKeyhole size={15}/><span>{error}</span></div>}
        <button className="btn btn-primary" type="submit" disabled={loading} style={{marginTop:18,width:'100%',justifyContent:'center'}}>{loading?<><LoaderCircle size={15} className="spin"/> Verifying access…</>:<><LogIn size={15}/> Login securely</>}</button>
      </form>
      <div className="role-entry-foot" style={{marginTop:18}}><span><LockKeyhole size={13}/> Backend authentication · JWT session · role-based access</span><span className="status status-neutral">Prototype security layer</span></div>
    </div>
  </div>;
}
