  const [reports,setReports]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [selected,setSelected]=useState<any>(); const [note,setNote]=useState(''); const [status,setStatus]=useState('Reviewed');
  useEffect(()=>{let active=true;setLoading(true);getReports(role).then(x=>{if(active){setReports(x);setLoading(false)}}).catch(e=>{if(active){setError(e instanceof Error?e.message:'Unable to load reports.');setLoading(false)}});return()=>{active=false}},[role]);
  const open=async(id:string)=>{try{setSelected(await getReportDetail(role,id))}catch(e){setError(e instanceof Error?e.message:'Unable to open report.')}};
  const review=async()=>{if(role!=='officer'||!selected?.report)return;try{await reviewCivilianReport(selected.report.id,status,note);setReports(r=>r.map(x=>x.id===selected.report.id?{...x,status,reviewNote:note}:x));setSelected((s:any)=>({...s,report:{...s.report,status,reviewNote:note}}));setNote('')}catch(e){setError(e instanceof Error?e.message:'Unable to update report.')}};
